<?php
declare(strict_types=1);
require __DIR__.'/bootstrap_saas.php';
$db=saas_db();$slug=trim((string)($_GET['slug']??''));$token=trim((string)($_GET['token']??''));
if($slug===''||!preg_match('/^[a-f0-9]{64}$/',$token)){http_response_code(404);exit('Booking link is invalid.');}
$hash=hash('sha256',$token);
$q=$db->prepare("SELECT tp.id tp_id,tp.status,pp.full_name,pp.phone,t.id tour_id,t.name tour_name,t.slug,t.organization_id FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id JOIN organizations o ON o.id=t.organization_id WHERE t.slug=? AND tp.booking_access_token_hash=? AND tp.booking_access_token_revoked_at IS NULL AND o.status='ACTIVE' LIMIT 1");$q->execute([$slug,$hash]);$booking=$q->fetch();
if(!$booking||$booking['status']!=='ACTIVE'){http_response_code(404);exit('Active booking not found.');}
$seatMsg='';$error='';
$q=$db->prepare("SELECT b.id,b.name,b.bus_number,b.layout_type,b.total_seats FROM buses b WHERE b.tour_id=? AND b.status='ACTIVE' ORDER BY b.id");$q->execute([(int)$booking['tour_id']]);$buses=$q->fetchAll();
$busId=(int)($_POST['bus_id']??$_GET['bus_id']??($buses[0]['id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['seat_id'])){try{$seatId=(int)$_POST['seat_id'];if(!$busId||!$seatId)throw new RuntimeException('Please select a seat.');$db->beginTransaction();$q=$db->prepare("SELECT s.id,s.seat_code,s.status FROM seats s JOIN buses b ON b.id=s.bus_id WHERE s.id=? AND s.bus_id=? AND b.tour_id=? FOR UPDATE");$q->execute([$seatId,$busId,(int)$booking['tour_id']]);$seat=$q->fetch();if(!$seat||$seat['status']!=='AVAILABLE')throw new RuntimeException('This seat is not available.');$q=$db->prepare('SELECT tour_passenger_id FROM passenger_seat_assignments WHERE seat_id=? AND bus_id=? FOR UPDATE');$q->execute([$seatId,$busId]);$occupied=$q->fetchColumn();if($occupied&&((int)$occupied!==(int)$booking['tp_id']))throw new RuntimeException('This seat has just been taken.');$q=$db->prepare('DELETE FROM passenger_seat_assignments WHERE tour_passenger_id=?');$q->execute([(int)$booking['tp_id']]);$q=$db->prepare('INSERT INTO passenger_seat_assignments(tour_passenger_id,bus_id,seat_id,assigned_by) VALUES(?,?,?,NULL)');$q->execute([(int)$booking['tp_id'],$busId,$seatId]);$db->commit();$seatMsg='Seat '.$seat['seat_code'].' has been selected successfully.';saas_audit('public.seat_selected','tour_passenger',(int)$booking['tp_id'],json_encode(['seat'=>$seat['seat_code'],'bus_id'=>$busId],JSON_UNESCAPED_UNICODE));}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$q=$db->prepare('SELECT s.id,s.seat_code,s.row_no,s.position,psa.tour_passenger_id FROM seats s LEFT JOIN passenger_seat_assignments psa ON psa.seat_id=s.id AND psa.bus_id=s.bus_id WHERE s.bus_id=? ORDER BY s.row_no,s.id');$q->execute([$busId]);$seats=$q->fetchAll();$mine=array_filter($seats,fn($s)=>(int)($s['tour_passenger_id']??0)===(int)$booking['tp_id']);$mySeat=$mine?array_values($mine)[0]:null;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Select Seat — <?=saas_h($booking['tour_name'])?></title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;font-family:Inter,Arial,sans-serif;color:#172033}.wrap{max-width:900px;margin:25px auto;padding:0 16px}.card{background:#fff;border-radius:18px;padding:22px;margin-bottom:18px;box-shadow:0 8px 30px #0000000b}.notice{padding:12px;border-radius:10px;background:#ecfdf3;color:#067647}.err{padding:12px;border-radius:10px;background:#fef3f2;color:#b42318}.busnav{display:flex;gap:8px;overflow:auto}.busnav a{padding:9px 12px;border:1px solid #d0d5dd;border-radius:9px;text-decoration:none;color:#172033;white-space:nowrap}.busnav a.active{background:#155eef;color:#fff;border-color:#155eef}.coach{max-width:600px;margin:20px auto;padding:25px;background:#eef2f6;border:1px solid #d0d5dd;border-radius:30px}.row{display:flex;justify-content:center;gap:9px;margin:9px 0}.seat{width:48px;height:42px;border:1px solid #98a2b3;border-radius:8px;background:#fff;display:flex;align-items:center;justify-content:center;font-size:12px}.seat.available{cursor:pointer}.seat.occupied{background:#d0d5dd;color:#667085}.seat.mine{background:#155eef;color:#fff;border-color:#155eef}.legend{display:flex;gap:15px;font-size:13px;justify-content:center;margin:15px}.dot{display:inline-block;width:13px;height:13px;border-radius:4px;background:#fff;border:1px solid #98a2b3;vertical-align:middle}.dot.o{background:#d0d5dd}.dot.m{background:#155eef}.muted{color:#667085;font-size:13px}@media(max-width:500px){.seat{width:40px;height:38px}.coach{padding:15px}}</style></head><body><main class="wrap"><section class="card"><h1><?=saas_h($booking['tour_name'])?></h1><p>Welcome, <strong><?=saas_h($booking['full_name'])?></strong> (<?=saas_h($booking['phone'])?>)</p><?php if($seatMsg):?><div class="notice"><?=saas_h($seatMsg)?></div><?php endif;?><?php if($error):?><div class="err"><?=saas_h($error)?></div><?php endif;?><p><strong>Current seat:</strong> <?=saas_h($mySeat['seat_code']??'Not selected')?></p></section><section class="card"><h2>Choose your bus</h2><div class="busnav"><?php foreach($buses as $b):?><a class="<?=((int)$b['id']===$busId?'active':'')?>" href="?slug=<?=rawurlencode($slug)?>&token=<?=rawurlencode($token)?>&bus_id=<?=$b['id']?>"><?=saas_h($b['name'])?><?=($b['bus_number' ]?' — '.saas_h($b['bus_number']):'')?></a><?php endforeach;?></div><h2>Select a seat</h2><div class="legend"><span><i class="dot"></i> Available</span><span><i class="dot o"></i> Taken</span><span><i class="dot m"></i> Yours</span></div><div class="coach"><?php $rows=[];foreach($seats as $s)$rows[$s['row_no']][]=$s;foreach($rows as $rs):?><div class="row"><?php foreach($rs as $s):$occupied=$s['tour_passenger_id']!==null;$mineSeat=(int)($s['tour_passenger_id']??0)===(int)$booking['tp_id'];?><?php if($mineSeat):?><div class="seat mine"><?=saas_h($s['seat_code'])?></div><?php elseif($occupied):?><div class="seat occupied"><?=saas_h($s['seat_code'])?></div><?php else:?><form method="post" style="margin:0"><input type="hidden" name="bus_id" value="<?=$busId?>"><input type="hidden" name="seat_id" value="<?=$s['id']?>"><button class="seat available" title="Select <?=saas_h($s['seat_code'])?>"><?=saas_h($s['seat_code'])?></button></form><?php endif;?><?php endforeach;?></div><?php endforeach;?></div><p class="muted">Seat availability is checked again when you select a seat. A seat can only be held by one passenger.</p></section></main></body></html>